package com.commercecore.order;import com.commercecore.user.Address;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="order_addresses")public class OrderAddress{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_id",nullable=false)private CustomerOrder order;@Enumerated(EnumType.STRING)@Column(name="address_type",nullable=false,length=16)private OrderAddressType type;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="source_address_id")private Address sourceAddress;@Column(name="recipient_name",nullable=false,length=150)private String recipientName;@Column(nullable=false,length=32)private String phone;@Column(name="address_line_1",nullable=false,length=200)private String addressLine1;@Column(name="address_line_2",length=200)private String addressLine2;@Column(nullable=false,length=100)private String city;@Column(name="state_region",nullable=false,length=100)private String stateRegion;@Column(name="postal_code",nullable=false,length=20)private String postalCode;@Column(name="country_code",nullable=false,length=2)private String countryCode;protected OrderAddress(){}public OrderAddress(CustomerOrder o,OrderAddressType t,Address a){order=o;type=t;sourceAddress=a;recipientName=a.getRecipientName();phone=a.getPhone();addressLine1=a.getAddressLine1();addressLine2=a.getAddressLine2();city=a.getCity();stateRegion=a.getStateRegion();postalCode=a.getPostalCode();countryCode=a.getCountryCode();}public UUID getId(){return id;}public OrderAddressType getType(){return type;}public UUID getSourceAddressId(){return sourceAddress==null?null:sourceAddress.getId();}public String getRecipientName(){return recipientName;}public String getPhone(){return phone;}public String getAddressLine1(){return addressLine1;}public String getAddressLine2(){return addressLine2;}public String getCity(){return city;}public String getStateRegion(){return stateRegion;}public String getPostalCode(){return postalCode;}public String getCountryCode(){return countryCode;}}
